    size_t len = strlen(buf);
    if (len >= buf_sz || buf[len - 1] != '\0') return -1;

    int ret = _write_pair(buf + len, buf_sz - len, key, val);
    if (ret == 0 && len > 0 && buf[len - 1] != ' ') {
        buf[len++] = ' ';
    }
    return ret;
